glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_LOCAL
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec4 color;
out vec2 uv0;
vec4 vert () {
  vec4 pos = vec4(a_position, 1.0);
  #if USE_LOCAL
    pos = cc_matWorld * pos;
  #endif
  #if USE_PIXEL_ALIGNMENT
    pos = cc_matView * pos;
    pos.xyz = floor(pos.xyz);
    pos = cc_matProj * pos;
  #else
    pos = cc_matViewProj * pos;
  #endif
  uv0 = a_texCoord;
  color = a_color;
  return pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  layout(std140) uniform ALPHA_TEST_DATA {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 color;
in vec2 uv0;
uniform sampler2D atlasTex;
uniform sampler2D gridTex;
layout(std140) uniform PreviewParams {
  vec4 board_data;
  vec4 style_data;
  vec4 gray_params;
  vec4 break_params;
  vec4 special_params;
  vec4 rot_params;
};
vec2 applyTiltUv(vec2 uv) {
  float x_rot = rot_params.x;
  float y_rot = rot_params.y;
  vec2 centered = uv - vec2(0.5, 0.5);
  vec2 parallax = vec2(y_rot, -x_rot) * 0.0022;
  float perspective =
    1.0 +
    centered.x * y_rot * 0.008 -
    centered.y * x_rot * 0.008;
  return centered / max(0.82, perspective)
    + vec2(0.5, 0.5)
    + parallax;
}
vec4 frag () {
  float gray_strength = gray_params.x;
  vec2 previewUv = applyTiltUv(uv0);
  vec2 boardSize = max(board_data.xy, vec2(1.0, 1.0));
  float atlasCols = max(board_data.z, 1.0);
  float atlasRows = max(board_data.w, 1.0);
  float cellInset = clamp(style_data.x, 0.0, 0.49);
  float fitNodeDirectly = step(0.5, style_data.y);
  vec2 boardUvSize = vec2(1.0, 1.0);
  vec2 boardUvMin = vec2(0.0, 0.0);
  vec2 boardUvMax = vec2(1.0, 1.0);
  if (fitNodeDirectly < 0.5) {
    float boardMaxDim = max(boardSize.x, boardSize.y);
    boardUvSize = boardSize / boardMaxDim;
    boardUvMin = (vec2(1.0, 1.0) - boardUvSize) * 0.5;
    boardUvMax = boardUvMin + boardUvSize;
    if (
      previewUv.x < boardUvMin.x ||
      previewUv.x > boardUvMax.x ||
      previewUv.y < boardUvMin.y ||
      previewUv.y > boardUvMax.y
    ) {
      discard;
    }
  }
  vec2 boardLocalUv =
    fitNodeDirectly >= 0.5
    ? previewUv
    : (previewUv - boardUvMin) / max(boardUvSize, vec2(0.0001));
  vec2 scaledUv = boardLocalUv * boardSize;
  vec2 cellCoord = floor(scaledUv);
  vec2 cellLocalUv = fract(scaledUv);
  cellLocalUv = mix(
    vec2(cellInset),
    vec2(1.0 - cellInset),
    cellLocalUv
  );
  vec2 gridUv = (cellCoord + vec2(0.5, 0.5)) / boardSize;
  float tileIndex = floor(texture(gridTex, gridUv).a * 255.0 + 0.5);
  if (tileIndex <= 0.0) {
    discard;
  }
  float atlasIndex = tileIndex - 1.0;
  float atlasCol = mod(atlasIndex, atlasCols);
  float atlasRow = floor(atlasIndex / atlasCols);
  vec2 atlasUv = vec2(
    (atlasCol + cellLocalUv.x) / atlasCols,
    (atlasRow + cellLocalUv.y) / atlasRows
  );
  vec4 outColor = texture(atlasTex, atlasUv) * color;
  float gray = dot(outColor.rgb, vec3(0.2126, 0.7152, 0.0722));
  outColor.rgb = mix(
    outColor.rgb,
    vec3(gray),
    clamp(gray_strength, 0.0, 1.0)
  );
  ALPHA_TEST(outColor);
  return outColor;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

glsl1.vert:
precision highp float;
uniform highp mat4 cc_matView;
  uniform highp mat4 cc_matProj;
  uniform highp mat4 cc_matViewProj;
#if USE_LOCAL
  uniform highp mat4 cc_matWorld;
#endif
attribute vec3 a_position;
attribute vec2 a_texCoord;
attribute vec4 a_color;
varying vec4 color;
varying vec2 uv0;
vec4 vert () {
  vec4 pos = vec4(a_position, 1.0);
